using System.Windows;using LibraryManager.Models;using LibraryManager.Services;namespace LibraryManager.Views;public partial class AddMemberWindow:Window{public AddMemberWindow(){InitializeComponent();string[] labels={"نام","نام خانوادگی","کد ملی","تلفن","نشانی"};var ts=new System.Windows.Controls.TextBox[5];for(int i=0;i<5;i++){Form.Children.Add(new System.Windows.Controls.TextBlock{Text=labels[i]});ts[i]=new System.Windows.Controls.TextBox();Form.Children.Add(ts[i]);}var b=new System.Windows.Controls.Button{Content="ثبت عضو و دریافت حق عضویت"};b.Click+=(s,e)=>{try{if(ts.Any(x=>string.IsNullOrWhiteSpace(x.Text)))throw new Exception("همه فیلدها را وارد کنید.");if(!PaymentDialog.ShowPayment("حق عضویت ۱۲ ماهه"))return;new MemberService().Register(new Member{FirstName=ts[0].Text,LastName=ts[1].Text,NationalId=ts[2].Text,PhoneNumber=ts[3].Text,Address=ts[4].Text},12,PaymentDialog.Method);DialogResult=true;}catch(Exception ex){MessageBox.Show(ex.Message);}};Form.Children.Add(b);}}